// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React, { useMemo } from "react";
import { AbsoluteFill, useCurrentFrame, useVideoConfig, spring, interpolate, random } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadCaveat = makeLoadFont('Caveat');

const { fontFamily: caveatFont } = loadCaveat();



export type FathersDayCardProps = Record<string, any>;

// Simple SVG Heart Component
const HeartIcon: React.FC<{ color: string }> = ({ color }) => (
  <svg viewBox="0 0 100 100" width="100%" height="100%" style={{ overflow: "visible" }}>
    <path
      d="M 50 85 C 10 50 10 20 30 10 C 42 4 50 15 50 15 C 50 15 58 4 70 10 C 90 20 90 50 50 85 Z"
      fill={color}
      stroke={color}
      strokeWidth="2"
      strokeLinejoin="round"
      style={{ transition: "none" }}
    />
  </svg>
);

// Stylized SVG Globe Component
const GlobeIcon: React.FC<{ waterColor: string; landColor: string }> = ({ waterColor, landColor }) => (
  <svg viewBox="0 0 100 100" width="100%" height="100%" style={{ overflow: "visible" }}>
    {/* Water */}
    <circle cx="50" cy="50" r="48" fill={waterColor} style={{ transition: "none" }} />
    {/* Landmasses (Stylized) */}
    <path d="M 15 45 Q 25 15 50 25 Q 65 30 55 50 Q 35 65 25 55 Q 10 50 15 45 Z" fill={landColor} style={{ transition: "none" }} />
    <path d="M 60 65 Q 75 45 85 55 Q 95 70 75 85 Q 50 90 60 65 Z" fill={landColor} style={{ transition: "none" }} />
    <path d="M 75 15 Q 95 15 85 35 Q 70 45 60 25 Q 60 10 75 15 Z" fill={landColor} style={{ transition: "none" }} />
    {/* Antarctica/Bottom ice */}
    <path d="M 30 85 Q 50 75 70 85 Q 60 98 40 98 Z" fill={landColor} style={{ transition: "none" }} />
  </svg>
);

const FathersDayCard: React.FC<FathersDayCardProps> = ({
  text1 = "to the",
  text2 = "BEST",
  text3 = "DAD",
  text4 = "in the",
  text5 = "WORLD",
  textColorMain = "#111111",
  accentColor1Fill = "#71C6FF", // Light blue marker fill
  accentColor1Stroke = "#3399FF", // Darker blue marker edge
  accentColor2 = "#008B8B", // Teal marker
  backgroundColor = "#F4F4F0", // Off-white paper
  lineColor = "#D0D0C8", // Light grey ruled lines
  heartColors = ["#80E5FF", "#00C2C2", "#B3F0FF", "#007A7A"],
  globeWaterColor = "#71C6FF",
  globeLandColor = "#A3E496",
  transparentBackground = false,
  durationInSeconds = 8,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Handle transparency
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Background Paper Lines
  const lineSpacing = 85;
  const numLines = Math.ceil(height / lineSpacing);
  const lines = useMemo(() => new Array(numLines).fill(0), [numLines]);

  // Generate Heart Positions and Properties (Memoized to prevent recalculation)
  const numHearts = 25;
  const hearts = useMemo(() => {
    return new Array(numHearts).fill(0).map((_, i) => {
      // Base random positions
      let x = random(i + "x") * width;
      let y = random(i + "y") * height;

      // Push hearts away from the center text area to match the reference image
      const safeZoneWidth = width * 0.6;
      const safeZoneHeight = height * 0.7;
      const centerX = width / 2;
      const centerY = height / 2;

      if (Math.abs(x - centerX) < safeZoneWidth / 2 && Math.abs(y - centerY) < safeZoneHeight / 2) {
        // If inside the safe zone, push it to the left or right edge
        x = random(i + "push") > 0.5 
          ? random(i + "L") * (width * 0.2) 
          : width * 0.8 + random(i + "R") * (width * 0.2);
      }

      return {
        x,
        y,
        scale: 0.3 + random(i + "s") * 0.4,
        rotation: (random(i + "r") - 0.5) * 80, // Random rotation between -40 and +40 deg
        color: heartColors[Math.floor(random(i + "c") * heartColors.length)],
        delay: random(i + "d") * 45, // Staggered entry
      };
    });
  }, [width, height, heartColors]);

  // Animation Timing Functions
  const popIn = (delay: number) =>
    spring({
      fps,
      frame: frame - delay,
      config: { damping: 12, mass: 0.8, stiffness: 120 },
    });

  // Staggered Text & Graphics Scales
  const t1Scale = popIn(10);
  const t2Scale = popIn(20);
  const t3Scale = popIn(30);
  const t4Scale = popIn(40);
  const t5Scale = popIn(50);
  const globeScale = popIn(65);

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: caveatFont, overflow: "hidden" }}>
      {/* Background Ruled Lines */}
      <AbsoluteFill style={{ display: "flex", flexDirection: "column", opacity: 0.7 }}>
        {lines.map((_, i) => (
          <div
            key={`line-${i}`}
            style={{
              width: "100%",
              height: lineSpacing,
              borderBottom: `2px solid ${lineColor}`,
              boxSizing: "border-box",
            }}
          />
        ))}
      </AbsoluteFill>

      {/* Scattered Floating Hearts */}
      {hearts.map((h, i) => {
        const hScale = spring({
          fps,
          frame: frame - h.delay,
          config: { damping: 10, stiffness: 100 },
        });
        
        // Gentle organic floating motion
        const floatY = Math.sin((frame - h.delay) * 0.04 + i) * 15;
        const opacity = interpolate(frame - h.delay, [0, 8], [0, 1], { extrapolateRight: "clamp" });

        return (
          <div
            key={`heart-${i}`}
            style={{
              position: "absolute",
              left: h.x,
              top: h.y,
              width: 80,
              height: 80,
              transform: `translateY(${floatY}px) scale(${hScale * h.scale}) rotate(${h.rotation}deg)`,
              opacity,
              transition: "none",
            }}
          >
            <HeartIcon color={h.color} />
          </div>
        );
      })}

      {/* Main Content Stack */}
      <AbsoluteFill
        style={{
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          justifyContent: "center",
          gap: 20, // Tighter gap, margin added specifically to elements
        }}
      >
        <div
          style={{
            transform: `scale(${t1Scale}) rotate(-1deg)`,
            fontSize: 100,
            color: textColorMain,
            fontWeight: 700,
            transition: "none",
          }}
        >
          {text1}
        </div>

        <div
          style={{
            transform: `scale(${t2Scale}) rotate(-3deg)`,
            fontSize: 220,
            color: accentColor1Fill,
            fontWeight: 800,
            WebkitTextStroke: `6px ${accentColor1Stroke}`, // Simulates thick marker outline
            letterSpacing: 4,
            marginTop: -20,
            transition: "none",
          }}
        >
          {text2}
        </div>

        <div
          style={{
            transform: `scale(${t3Scale}) rotate(2deg)`,
            fontSize: 150,
            color: accentColor2,
            fontWeight: 800,
            marginTop: 10,
            transition: "none",
          }}
        >
          {text3}
        </div>

        <div
          style={{
            transform: `scale(${t4Scale}) rotate(1deg)`,
            fontSize: 100,
            color: textColorMain,
            fontWeight: 700,
            marginTop: 10,
            transition: "none",
          }}
        >
          {text4}
        </div>

        <div
          style={{
            transform: `scale(${t5Scale}) rotate(-1deg)`,
            fontSize: 130,
            color: textColorMain,
            fontWeight: 800,
            marginTop: 0,
            transition: "none",
          }}
        >
          {text5}
        </div>

        {/* Drawn Globe Icon */}
        <div
          style={{
            transform: `scale(${globeScale}) rotate(2deg)`,
            width: 250,
            height: 250,
            marginTop: 40,
            transition: "none",
          }}
        >
          <GlobeIcon waterColor={globeWaterColor} landColor={globeLandColor} />
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

export default FathersDayCard;